_INSPECTOR_URL_TEMPLATE = (
    "{rasa_server_url}/webhooks/inspector/inspect.html?sender={conversation_id}"
)
_RASA_HTTP_TIMEOUT = 10.0


async def _trigger_session_start(
    session: aiohttp.ClientSession,
    conversation_id: str,
    rasa_url: str,
    *,
    session_start_metadata: Optional[Dict[str, Any]] = None,
) -> List[str]:
    """Bootstrap ``/session_start`` before the first real user turn.

    Matches Inspector welcome-first ordering: session start runs on an empty
    tracker so any configured greeting is uttered before simulation content.
    When ``initial_slots`` are injected afterward, they intentionally override
    slots set during session start.

    Args:
        session: Open ``aiohttp.ClientSession`` shared with the simulation loop.
        conversation_id: Rasa conversation (sender) id.
        rasa_url: Base URL of the running Rasa server (no trailing slash).
        session_start_metadata: Optional channel-style metadata merged into the
            ``/session_start`` webhook payload (after ``is_simulation``).

    Returns:
        Bot reply texts from the session-start turn (empty when no greeting
        was configured or returned).

    Raises:
        RuntimeError: when all send retries are exhausted (from ``_send_message``).
    """
    metadata: Dict[str, Any] = dict(session_start_metadata or {})
    metadata["is_simulation"] = True
    return (
        await _send_message(
            session,
            conversation_id,
            USER_CONVERSATION_SESSION_START,
            rasa_url,
            metadata=metadata,
        )
    ).texts


async def _set_initial_slots(
    session: aiohttp.ClientSession,
    conversation_id: str,
    slots: Dict[str, Any],
    rasa_url: str,
) -> None:
    """POST slot events to the tracker before simulation begins.

    Sends a batch of ``slot`` events to the Rasa tracker endpoint so that
    the conversation starts with the specified slot values already set.
    Does nothing when ``slots`` is empty.

    Args:
        session: Open ``aiohttp.ClientSession`` shared with the simulation loop.
        conversation_id: Rasa conversation (sender) id to inject slots into.
        slots: Mapping of slot name to initial value from the scenario setup.
        rasa_url: Base URL of the running Rasa server (no trailing slash).

    Returns:
        None.

    Raises:
        aiohttp.ClientResponseError: If the Rasa server returns a non-2xx status.
        aiohttp.ClientError: On connection or timeout failures.
    """
    if not slots:
        return
    url = f"{rasa_url}/conversations/{conversation_id}/tracker/events"
    events = [{"event": "slot", "name": k, "value": v} for k, v in slots.items()]
    async with session.post(
        url,
        json=events,
        timeout=aiohttp.ClientTimeout(total=_RASA_HTTP_TIMEOUT),
    ) as resp:
        resp.raise_for_status()


async def _fetch_engine_token_usage(
    session: aiohttp.ClientSession,
    conversation_id: str,
    rasa_server_url: str,
) -> Dict[str, Any]:
    """Fetch accumulated engine token usage for a conversation."""
    url = f"{rasa_server_url.rstrip('/')}/conversations/{conversation_id}/engine_tokens"

    try:
        async with session.get(
            url, timeout=aiohttp.ClientTimeout(total=_RASA_HTTP_TIMEOUT)
        ) as resp:
            resp.raise_for_status()
            payload = await resp.json()
            if isinstance(payload, dict):
                return payload
    except Exception as exc:
        structlogger.warning(
            "evaluate_agent.fetch_engine_tokens.failed",
            conversation_id=conversation_id,
            error=str(exc),
        )
        return {
            "status": "error",
            "session_id": conversation_id,
            "error": str(exc)[:500],
        }

    return {
        "status": "error",
        "session_id": conversation_id,
        "error": "invalid engine token response",
    }


async def _fetch_engine_version(
    session: aiohttp.ClientSession, rasa_server_url: str
) -> str:
    """Read ``engine_version`` from the running server's ``/status``."""
    url = f"{rasa_server_url.rstrip('/')}/status"
    timeout = aiohttp.ClientTimeout(total=30)
    try:
        async with session.get(url, timeout=timeout) as response:
            response.raise_for_status()
            payload = await response.json()
    except aiohttp.ClientError as exc:
        raise EvalScenarioError(f"Could not read engine_version from {url}") from exc
    version = payload.get("engine_version") if isinstance(payload, dict) else None
    if not isinstance(version, str) or not version:
        raise EvalScenarioError("Server /status did not include engine_version")
    return version


async def _fetch_tracker_events(
    conversation_id: str,
    rasa_server_url: str,
    *,
    session: Optional[aiohttp.ClientSession] = None,
) -> list:
    """Fetch and deserialize tracker events for a conversation.

    Args:
        conversation_id: The conversation (sender) ID.
        rasa_server_url: Base URL of the running Rasa server.
        session: Optional open ``aiohttp.ClientSession`` to reuse; a new one
            is created (and closed) when omitted.

    Returns:
        List of deserialized Event objects.
    """
    from rasa.shared.core.events import deserialise_events

    url = f"{rasa_server_url.rstrip('/')}/conversations/{conversation_id}/tracker"

    async def _get(s: aiohttp.ClientSession) -> Dict[str, Any]:
        async with s.get(url, timeout=aiohttp.ClientTimeout(total=30)) as resp:
            resp.raise_for_status()
            return await resp.json()

    if session is not None:
        data = await _get(session)
    else:
        async with aiohttp.ClientSession() as _session:
            data = await _get(_session)

    return deserialise_events(data.get("events", []))


def _is_content_user_uttered(event: Any) -> bool:
    """Return whether ``event`` is a user message other than ``/session_start``."""
    if not isinstance(event, UserUttered):
        return False
    text = (event.text or "").strip()
    return bool(text) and text != USER_CONVERSATION_SESSION_START


def _bot_uttered_text(event: Any) -> Optional[str]:
    """Return non-empty bot text from a ``BotUttered`` event."""
    if not isinstance(event, BotUttered):
        return None
    text = event.text
    if not isinstance(text, str) or not text:
        return None
    return text


def _tracker_bot_slices(
    events: List[Any],
) -> tuple[List[str], List[List[str]]]:
    """Group tracker ``BotUttered`` texts into welcome vs per-user-turn slices.

    ``/session_start`` does not open a content slice, so greeting utterances
    stay on the welcome list. Each later ``UserUttered`` starts a new slice.
    """
    welcome: List[str] = []
    content_slices: List[List[str]] = []
    current = welcome
    for event in events:
        if _is_content_user_uttered(event):
            current = []
            content_slices.append(current)
            continue
        bot_text = _bot_uttered_text(event)
        if bot_text is not None:
            current.append(bot_text)
    return welcome, content_slices


def _overlay_turn_bot_from_tracker(
    turns: List[SimulationTurn],
    events: List[Any],
) -> List[SimulationTurn]:
    """Replace glued SSE ``bot`` lists with tracker utterance boundaries.

    Keeps SSE-derived ``ttft_ms`` / ``turn_latency_ms``. Empty tracker slices
    leave the stream texts in place so a lagged tracker store does not wipe
    the transcript. Voice/Coval transcripts must not call this.
    """
    if not turns:
        return turns

    welcome, content_slices = _tracker_bot_slices(events)
    _warn_on_overlay_length_mismatch(turns, content_slices)
    return _apply_tracker_bot_slices(turns, welcome, content_slices)


def _warn_on_overlay_length_mismatch(
    turns: List[SimulationTurn],
    content_slices: List[List[str]],
) -> None:
    """Log when the tracker and the simulation disagree on user turn count."""
    content_turn_count = sum(1 for turn in turns if turn.user.strip())
    if not content_slices or content_turn_count == len(content_slices):
        return
    structlogger.warning(
        "rasa.simulation.overlay.length_mismatch",
        content_turns=content_turn_count,
        tracker_user_turns=len(content_slices),
    )


def _apply_tracker_bot_slices(
    turns: List[SimulationTurn],
    welcome: List[str],
    content_slices: List[List[str]],
) -> List[SimulationTurn]:
    """Write tracker utterances onto each turn, keeping stream texts on gaps."""
    content_index = 0
    overlaid: List[SimulationTurn] = []
    for turn in turns:
        if not turn.user.strip():
            if welcome:
                turn = turn.model_copy(update={"bot": list(welcome)})
        else:
            if content_index < len(content_slices) and content_slices[content_index]:
                turn = turn.model_copy(
                    update={"bot": list(content_slices[content_index])}
                )
            content_index += 1
        overlaid.append(turn)
    return overlaid


async def _simulate_scenario(
    scenario: Scenario,
    *,
    conversation_id: str,
    rasa_url: str,
    rasa_server_url: str,
    simulation_llm_client: LLMClient,
    simulated_user_prompt: Optional[str],
    show_tracker_events: bool,
    project_memory: ProjectMemorySchema,
    simulation_llm_semaphore: Optional[asyncio.Semaphore] = None,
) -> tuple[
    List[SimulationTurn],
    List[Dict[str, Any]],
    List[Any],
    Optional[str],
    Optional[Dict[str, Any]],
]:
    """Run text simulation and return turns, events, debug text, and token usage.

    After the REST stream closes, ``turn.bot`` is overlaid from tracker
    ``BotUttered`` events so token fragments stay one utterance and separate
    utterances stay separate. Stream timings are left unchanged.
    """
    engine_tokens: Optional[Dict[str, Any]] = None
    session_start_metadata, post_session_start_slots = partition_initial_slots(
        scenario.setup.initial_slots, project_memory
    )
    async with aiohttp.ClientSession() as session:
        # Always bootstrap session start before content turns (and before slot
        # injection) so a configured welcome is uttered first, matching Inspector.
        welcome_messages = await _trigger_session_start(
            session,
            conversation_id,
            rasa_url,
            session_start_metadata=session_start_metadata or None,
        )
        # Non-seed initial_slots are injected after session start, so they
        # intentionally override any slots that session start set.
        await _set_initial_slots(
            session, conversation_id, post_session_start_slots, rasa_url
        )
        sim_kwargs: Dict[str, Any] = {
            "initial_bot_messages": welcome_messages,
        }
        if simulated_user_prompt is not None:
            sim_kwargs["prompt_template"] = simulated_user_prompt
        turn_dicts = await run_text_simulation(
            scenario,
            simulation_llm_client,
            session,
            conversation_id,
            rasa_url,
            llm_semaphore=simulation_llm_semaphore,
            **sim_kwargs,
        )
        events = await _fetch_tracker_events(
            conversation_id, rasa_server_url, session=session
        )
        turns = _overlay_turn_bot_from_tracker(
            _turn_dicts_to_simulation_turns(turn_dicts), events
        )
        turn_dicts = [turn.model_dump() for turn in turns]
        if extended_eval_enabled():
            engine_tokens = await _fetch_engine_token_usage(
                session, conversation_id, rasa_server_url
            )
        tracker_events = (
            format_tracker_events_debug(events) if show_tracker_events else None
        )
    return turns, turn_dicts, events, tracker_events, engine_tokens


def _score_expected_tool_calls(
    *,
    events: List[Any],
    scenario: Scenario,
    evaluate_tool_calls: bool,
    run_index: int,
) -> tuple[List[ObservedTool], ToolScoresPerConversation | None]:
    """Score observed tool calls against scenario expectations when enabled."""
    if not evaluate_tool_calls:
        return [], None

    observed_tools = get_tools_from_events(events)
    tool_scoring_result = score_tools(
        observed_tools,
        scenario.goals.expected_tools,
    )
    if observed_tools:
        structlogger.info(
            "evaluate_agent.observed_tools",
            scenario=scenario.name,
            run_index=run_index,
            tool_count=len(observed_tools),
            has_expected_tools=bool(scenario.goals.expected_tools),
        )
    return observed_tools, tool_scoring_result


async def _evaluate_scenario_run(
    *,
    scenario: Scenario,
    turn_dicts: List[Dict[str, Any]],
    turns: List[SimulationTurn],
    events: List[Any],
    conversation_id: str,
    eval_llm_client: LLMClient,
    eval_llm_config: LLMConfig,
    criteria_judge_prompt: Optional[str],
    metrics_judge_prompt: Optional[str],
    engine_version: str,
    eval_llm_semaphore: Optional[asyncio.Semaphore] = None,
) -> tuple[List[AssertionResult], List[CriterionResult], LlmJudgeResults]:
    """Evaluate deterministic assertions and LLM judge criteria for one run."""
    # For multi-turn scenarios, only the last user utterance is available
    # as step_text; use criteria for generative quality in those cases.
    # Generative assertions call the judge LLM synchronously, so running this
    # inline would block the event loop and serialise every other run in the
    # batch behind it.
    #
    # Known limit: to_thread makes the *await* cancellable, not the work. If a
    # run's timeout fires during a generative assertion, the worker thread
    # keeps going until the provider call returns -- so cancellation bounds
    # when the batch moves on, not when the LLM spend stops. Bounded in
    # practice by the provider's own timeout and by parallelism staying well
    # under the default executor's worker count. Removing the caveat means an
    # async assertion path in rasa/e2e_test/assertions.py, which is shared with
    # e2e testing and out of scope here.
    # Held across the offload so generative assertions, which call the
    # evaluation provider synchronously inside the worker thread, are bounded
    # by the same ceiling as the judge. The slot is taken before the work is
    # handed to the thread, which bounds how many of these *start* at once.
    # It does not bound completion: cancelling the await (a per-run timeout)
    # exits this block and frees the slot while the thread is still inside the
    # provider call, so a timed-out batch can briefly exceed the ceiling.
    async with eval_llm_semaphore or nullcontext():
        assertion_results = await asyncio.to_thread(
            evaluate_assertions,
            scenario.goals.assertions,
            events,
            llm_config=eval_llm_config,
            step_text=turns[-1].user if turns else None,
        )

    judge_kwargs: Dict[str, Any] = {
        "events": events,
        "conversation_id": conversation_id,
        "engine_version": engine_version,
    }
    if criteria_judge_prompt is not None:
        judge_kwargs["criteria_prompt_template"] = criteria_judge_prompt
    if metrics_judge_prompt is not None:
        judge_kwargs["metrics_prompt_template"] = metrics_judge_prompt
    judge_results = await run_llm_as_a_judge(
        scenario,
        turn_dicts,
        eval_llm_client,
        llm_semaphore=eval_llm_semaphore,
        **judge_kwargs,
    )
    return assertion_results, judge_results.criteria.results, judge_results


def _scenario_run_passed(
    *,
    assertion_results: List[AssertionResult],
    criteria_results: List[CriterionResult],
    scenario: Scenario,
    judge_results: LlmJudgeResults,
    evaluate_tool_calls: bool,
    tool_scoring_result: ToolScoresPerConversation | None,
) -> bool:
    """Return whether assertions, criteria, and gated tool calls all passed."""
    # Quality metrics (scale + binary) are informational only and intentionally
    # excluded from gating `passed`. A failed binary metric like task_completion
    # may reflect a system issue outside the bot's control, not a bot defect.
    # If task completion must gate a run, add it as an explicit
    # criterion instead.
    assertions_passed = all(r.passed for r in assertion_results)
    criteria_passed = all(r.passed for r in criteria_results)
    criteria_judge_ok = not (
        scenario.goals.criteria and judge_results.criteria.error is not None
    )
    tool_gates_passed = (
        not evaluate_tool_calls
        or tool_scoring_result is None
        or all(
            entry.gate_passed for entry in tool_scoring_result.per_entry if entry.gate
        )
    )
    return (
        assertions_passed
        and criteria_passed
        and criteria_judge_ok
        and tool_gates_passed
    )


def _persist_run_report(
    report: RunReport,
    project_path: Path,
    experiment_timestamp: str,
) -> None:
    """Write the run report and optionally log it to Weights & Biases."""
    try:
        report_file_path = write_run_report(project_path, experiment_timestamp, report)
    except Exception as exc:
        structlogger.warning(
            "evaluate_agent.run_once.write_report_failed",
            scenario=report.scenario_name,
            run_index=report.run_index,
            error=str(exc),
        )
        return

    if not _wandb_logging_enabled():
        return

    try:
        _log_run_report_to_wandb(report, report_file_path)
    except Exception as exc:
        structlogger.warning(
            "evaluate_agent.run_once.wandb_logging_failed",
            scenario=report.scenario_name,
            run_index=report.run_index,
            error=str(exc),
        )


def _effective_evaluate_tool_calls(evaluate_tool_calls: bool) -> bool:
    """Score tools only when the caller asked and the extended-eval flag is on."""
    return bool(evaluate_tool_calls) and extended_eval_enabled()


def _effective_coval_context(
    coval_context: Optional[CovalRunContext],
) -> Optional[CovalRunContext]:
    """Drop Coval metadata unless the extended-eval flag is on."""
    if coval_context is None or not extended_eval_enabled():
        return None
    return coval_context


def _repair_occurrences_for_events(events: List[Any]) -> List[Any]:
    """Compute repair occurrences only when the extended-eval flag is on."""
    if not extended_eval_enabled():
        return []
    return deduce_repair_occurrences(events)


def _wandb_logging_enabled() -> bool:
    if not extended_eval_enabled():
        return False
    if os.environ.get("REPORT_TO_WANDB", "false").strip().lower() != "true":
        return False
    if not find_spec("wandb"):
        structlogger.warning(
            "evaluate_agent.wandb_logging_disabled",
            reason="dependency_missing",
            dependency="wandb",
        )
        return False
    if not os.environ.get("WANDB_API_KEY"):
        structlogger.warning(
            "evaluate_agent.wandb_logging_disabled",
            reason="api_key_missing",
            env_var="WANDB_API_KEY",
        )
        return False
    return True


def _log_run_report_to_wandb(report: RunReport, report_file_path: Path) -> None:
    def _sanitise_data_key_name(key: str) -> str:
        """Ensure metric name complies with WandB requirements.

        https://docs.wandb.ai/models/track/log#metric-naming-constraints

        Args:
            key (str): Raw key name

        Returns:
            str: Sanitised key name, that complies with WandB requirements
        """
        key = re.sub(r"[^_a-zA-Z0-9]+", "_", key)

        if not key:
            return "_"

        if not re.match(r"[_a-zA-Z]", key[0]):
            key = "_" + key

        return key

    agent = os.environ.get("EVAL_AGENT", "Unknown")
    name = f"Orchestrator: {agent} agent"

    import wandb

    with wandb.init(
        entity=os.environ.get("WANDB_ENTITY") or "Rasa-Engine",
        project=os.environ.get("WANDB_PROJECT") or "Mantle",
        # Track run metadata
        config={
            "Scenario name": report.scenario_name,
            "Scenario slug": report.scenario_slug,
            "Conversation ID": report.conversation_id,
        },
        group=f"{agent} agent",
        name=f"{os.environ.get('RUN_NAME') or name} {report.timestamp}",
        notes="All scores are on a scale of 1 - 5 (Lowest 1, Max 5)",
    ) as run:
        # Prepare data to be logged
        data = {
            "Overall": "PASS" if report.passed else "FAIL",
            "Run": report.run_index,
            "Duration_s": report.duration_s,
        }

        if report.criteria_results:
            for criterion in report.criteria_results:
                criterion_key = _sanitise_data_key_name(criterion.criterion)
                data[f"criterion_{criterion_key}_result"] = (
                    "PASS" if criterion.passed else "FAIL"
                )
                data[f"criterion_{criterion_key}_reasoning"] = criterion.reasoning

        judge_results = report.judge_results
        if judge_results:
            metrics = judge_results.metrics
            if not metrics.error:
                if judge_results.bot_quality is not None:
                    data["Quality_Score"] = judge_results.bot_quality
                for key, scale_result in metrics.scale_metrics.items():
                    data[_sanitise_data_key_name(f"{key}_score")] = scale_result.score
                    data[_sanitise_data_key_name(f"{key}_score_reasoning")] = (
                        scale_result.reasoning
                    )
                for key, bin_result in metrics.binary_metrics.items():
                    status = "PASS" if bin_result.passed else "FAIL"
                    data[_sanitise_data_key_name(f"{key}_result")] = status
                    data[_sanitise_data_key_name(f"{key}_result_reasoning")] = (
                        bin_result.reasoning
                    )
                if metrics.summary:
                    data["summary"] = metrics.summary

        if report.assertion_results:
            from rasa.builder.copilot.mcp_server.tools.artifact_writer import (
                _assertion_label,
            )

            for assertion in report.assertion_results:
                label = _assertion_label(assertion.assertion)
                status = "PASS" if assertion.passed else "FAIL"
                data[f"{_sanitise_data_key_name(label)}_result"] = status
                if assertion.detail:
                    data[f"{_sanitise_data_key_name(label)}_detail"] = assertion.detail

        if tool_scores := report.tool_scoring:
            if tool_scores.accuracy is not None:
                data["Tools_accuracy"] = tool_scores.accuracy
            if tool_scores.precision is not None:
                data["Tools_precision"] = tool_scores.precision
            if tool_scores.recall is not None:
                data["Tools_recall"] = tool_scores.recall
            if failure_reason := tool_scores.failure_reason:
                data["failure_reason"] = failure_reason

        # Log data to wandb.
        run.log(data)

        # Store `run_<N>.txt` as artifact
        run.log_artifact(report_file_path)


_TRANSCRIPT_ONLY_NOTE = (
    "Voice eval: transcript-only (no conversation_id); deterministic assertions "
    "and tool scoring were skipped."
)


@dataclass(frozen=True)
class CovalRunContext:
    """Coval run metadata attached to a voice benchmark artifact."""

    run_id: Optional[str] = None
    simulation_id: Optional[str] = None
    metrics: Optional[List[Dict[str, Any]]] = None


def _turn_dicts_to_simulation_turns(
    turn_dicts: List[Dict[str, Any]],
) -> List[SimulationTurn]:
    """Build ``SimulationTurn`` models from text-simulation-style turn dicts."""
    return [
        SimulationTurn(
            user=t["user"],
            bot=t["bot"],
            ttft_ms=t.get("ttft_ms"),
            turn_latency_ms=t.get("turn_latency_ms"),
            gaps_ms=t.get("gaps_ms", []),
        )
        for t in turn_dicts
    ]


async def evaluate_from_turn_dicts(
    scenario: Scenario,
    turn_dicts: List[Dict[str, Any]],
    run_index: int,
    project_path: Path,
    experiment_timestamp: str,
    rasa_server_url: str,
    eval_llm_client: LLMClient,
    eval_llm_config: LLMConfig,
    *,
    conversation_id: Optional[str] = None,
    criteria_judge_prompt: Optional[str] = None,
    metrics_judge_prompt: Optional[str] = None,
    show_tracker_events: bool = False,
    evaluate_tool_calls: bool = False,
    coval_context: Optional[CovalRunContext] = None,
    engine_version: str = CALM_ENGINE_VERSION,
) -> RunReport:
    """Evaluate a pre-built transcript instead of running text simulation.

    When ``conversation_id`` is omitted, only LLM judge criteria run on the
    transcript; deterministic assertions and tool scoring are skipped.
    ``engine_version`` selects the event vocabulary the criteria judge is told
    to read; callers judging a Mantle agent must pass it explicitly.

    Voice/Coval path: turn text comes from the external transcript (Coval), not the
    tracker. ``conversation_id`` only enables an optional tracker fetch for
    assertions/tools; it is not auto-linked to the voice session today
    (TODO ENG-3115: controllable sender_id / X-Rasa-Sender).
    """
    timestamp = datetime.now(tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    resolved_conversation_id = conversation_id or f"voice-{uuid.uuid4()}"
    rasa_url = rasa_server_url.rstrip("/")
    error: Optional[str] = None
    error_is_harness = True
    turns = _turn_dicts_to_simulation_turns(turn_dicts)
    events: List[Any] = []
    assertion_results: List[AssertionResult] = []
    criteria_results: List[CriterionResult] = []
    judge_results: Optional[LlmJudgeResults] = None
    engine_tokens: Optional[Dict[str, Any]] = None
    tool_scoring_result: ToolScoresPerConversation | None = None
    observed_tools: List[ObservedTool] = []
    tracker_events: Optional[str] = None
    passed = False
    _start = time.perf_counter()
    transcript_only = conversation_id is None
    evaluate_tool_calls = _effective_evaluate_tool_calls(evaluate_tool_calls)
    coval_context = _effective_coval_context(coval_context)
    coval_run_id = coval_context.run_id if coval_context else None
    coval_simulation_id = coval_context.simulation_id if coval_context else None
    coval_metrics = coval_context.metrics if coval_context else None

    with bound_contextvars(conversation_id=resolved_conversation_id):
        try:
            if transcript_only:
                tracker_events = _TRANSCRIPT_ONLY_NOTE
                judge_kwargs: Dict[str, Any] = {
                    "events": events,
                    "conversation_id": resolved_conversation_id,
                    "engine_version": engine_version,
                }
                if criteria_judge_prompt is not None:
                    judge_kwargs["criteria_prompt_template"] = criteria_judge_prompt
                if metrics_judge_prompt is not None:
                    judge_kwargs["metrics_prompt_template"] = metrics_judge_prompt
                # No semaphore: this path judges one supplied transcript per
                # call with no batch behind it, so no per-role ceiling is in
                # scope here.
                judge_results = await run_llm_as_a_judge(
                    scenario,
                    turn_dicts,
                    eval_llm_client,
                    **judge_kwargs,
                )
                criteria_results = judge_results.criteria.results
            else:
                async with aiohttp.ClientSession() as session:
                    events = await _fetch_tracker_events(
                        resolved_conversation_id,
                        rasa_server_url,
                        session=session,
                    )
                    if extended_eval_enabled():
                        engine_tokens = await _fetch_engine_token_usage(
                            session,
                            resolved_conversation_id,
                            rasa_server_url,
                        )
                    tracker_events = (
                        format_tracker_events_debug(events)
                        if show_tracker_events
                        else None
                    )
                observed_tools, tool_scoring_result = _score_expected_tool_calls(
                    events=events,
                    scenario=scenario,
                    evaluate_tool_calls=evaluate_tool_calls,
                    run_index=run_index,
                )
                (
                    assertion_results,
                    criteria_results,
                    judge_results,
                ) = await _evaluate_scenario_run(
                    scenario=scenario,
                    turn_dicts=turn_dicts,
                    turns=turns,
                    events=events,
                    conversation_id=resolved_conversation_id,
                    eval_llm_client=eval_llm_client,
                    eval_llm_config=eval_llm_config,
                    criteria_judge_prompt=criteria_judge_prompt,
                    metrics_judge_prompt=metrics_judge_prompt,
                    engine_version=engine_version,
                )
            passed = _scenario_run_passed(
                assertion_results=assertion_results,
                criteria_results=criteria_results,
                scenario=scenario,
                judge_results=judge_results,
                evaluate_tool_calls=evaluate_tool_calls and not transcript_only,
                tool_scoring_result=tool_scoring_result,
            )
        except asyncio.CancelledError:
            raise
        except NothingToJudgeError as exc:
            error = str(exc)
            error_is_harness = False
            structlogger.warning(
                "evaluate_agent.from_turn_dicts.agent_produced_nothing",
                scenario=scenario.name,
                run_index=run_index,
                conversation_id=resolved_conversation_id,
                error=error,
            )
        except Exception as exc:
            error = str(exc)
            structlogger.warning(
                "evaluate_agent.from_turn_dicts.error",
                scenario=scenario.name,
                run_index=run_index,
                conversation_id=resolved_conversation_id,
                error=error,
                traceback=traceback.format_exc(),
            )

    duration_s = time.perf_counter() - _start
    inspector_url = _INSPECTOR_URL_TEMPLATE.format(
        rasa_server_url=rasa_url,
        conversation_id=resolved_conversation_id,
    )

    report = RunReport(
        scenario_name=scenario.name,
        scenario_slug=scenario.slug,
        run_index=run_index,
        timestamp=timestamp,
        conversation_id=resolved_conversation_id,
        passed=passed,
        turns=turns,
        assertion_results=assertion_results,
        criteria_results=criteria_results,
        inspector_url=inspector_url,
        error=error,
        error_is_harness=error_is_harness,
        judge_results=judge_results,
        engine_tokens=engine_tokens,
        duration_s=duration_s,
        tool_scoring=tool_scoring_result,
        observed_tools=observed_tools,
        expected_tools=scenario.goals.expected_tools,
        tracker_events=tracker_events,
        evaluate_tool_calls=evaluate_tool_calls and not transcript_only,
        repair_occurrences=_repair_occurrences_for_events(events),
        coval_run_id=coval_run_id,
        coval_simulation_id=coval_simulation_id,
        coval_metrics=coval_metrics,
    )
    _persist_run_report(report, project_path, experiment_timestamp)
    return report


async def _run_once(
    scenario: Scenario,
    run_index: int,
    project_path: Path,
    experiment_timestamp: str,
    rasa_server_url: str,
    simulation_llm_client: LLMClient,
    eval_llm_client: LLMClient,
    eval_llm_config: LLMConfig,
    simulated_user_prompt: Optional[str] = None,
    criteria_judge_prompt: Optional[str] = None,
    metrics_judge_prompt: Optional[str] = None,
    show_tracker_events: bool = False,
    evaluate_tool_calls: bool = False,
    project_memory: Optional[ProjectMemorySchema] = None,
    simulation_llm_semaphore: Optional[asyncio.Semaphore] = None,
    eval_llm_semaphore: Optional[asyncio.Semaphore] = None,
    engine_version: str = CALM_ENGINE_VERSION,
) -> RunReport:
    """Run the scenario once, write the run report and return it.

    Orchestrates text simulation, tracker fetching, deterministic assertion
    evaluation, LLM-as-a-judge evaluation, artifact writing and (if applicable),
    logging the run to 'Weights and Biases'.
    """
    timestamp = datetime.now(tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    conversation_id = f"sim-{uuid.uuid4()}"
    rasa_url = rasa_server_url.rstrip("/")
    error: Optional[str] = None
    error_is_harness = True
    turns: List[SimulationTurn] = []
    events: List[Any] = []
    assertion_results: List[AssertionResult] = []
    criteria_results: List[CriterionResult] = []
    judge_results: Optional[LlmJudgeResults] = None
    engine_tokens: Optional[Dict[str, Any]] = None
    tool_scoring_result: ToolScoresPerConversation | None = None
    observed_tools: List[ObservedTool] = []
    tracker_events: Optional[str] = None
    passed = False
    _start = time.perf_counter()
    evaluate_tool_calls = _effective_evaluate_tool_calls(evaluate_tool_calls)
    resolved_project_memory = project_memory or load_project_memory_schema(project_path)

    with bound_contextvars(conversation_id=conversation_id):
        try:
            (
                turns,
                turn_dicts,
                events,
                tracker_events,
                engine_tokens,
            ) = await _simulate_scenario(
                scenario,
                conversation_id=conversation_id,
                rasa_url=rasa_url,
                rasa_server_url=rasa_server_url,
                simulation_llm_client=simulation_llm_client,
                simulated_user_prompt=simulated_user_prompt,
                show_tracker_events=show_tracker_events,
                project_memory=resolved_project_memory,
                simulation_llm_semaphore=simulation_llm_semaphore,
            )
            observed_tools, tool_scoring_result = _score_expected_tool_calls(
                events=events,
                scenario=scenario,
                evaluate_tool_calls=evaluate_tool_calls,
                run_index=run_index,
            )
            (
                assertion_results,
                criteria_results,
                judge_results,
            ) = await _evaluate_scenario_run(
                scenario=scenario,
                turn_dicts=turn_dicts,
                turns=turns,
                events=events,
                conversation_id=conversation_id,
                eval_llm_client=eval_llm_client,
                eval_llm_config=eval_llm_config,
                criteria_judge_prompt=criteria_judge_prompt,
                metrics_judge_prompt=metrics_judge_prompt,
                engine_version=engine_version,
                eval_llm_semaphore=eval_llm_semaphore,
            )
            passed = _scenario_run_passed(
                assertion_results=assertion_results,
                criteria_results=criteria_results,
                scenario=scenario,
                judge_results=judge_results,
                evaluate_tool_calls=evaluate_tool_calls,
                tool_scoring_result=tool_scoring_result,
            )
        except asyncio.CancelledError:
            raise
        except NothingToJudgeError as exc:
            # The run reached the agent and the agent said nothing. That is a
            # verdict on the agent, not the harness failing to get one.
            error = str(exc)
            error_is_harness = False
            structlogger.warning(
                "evaluate_agent.run_once.agent_produced_nothing",
                scenario=scenario.name,
                run_index=run_index,
                conversation_id=conversation_id,
                error=error,
            )
        except Exception as exc:
            error = str(exc)
            structlogger.warning(
                "evaluate_agent.run_once.error",
                scenario=scenario.name,
                run_index=run_index,
                conversation_id=conversation_id,
                error=error,
                traceback=traceback.format_exc(),
            )

    duration_s = time.perf_counter() - _start
    inspector_url = _INSPECTOR_URL_TEMPLATE.format(
        rasa_server_url=rasa_url,
        conversation_id=conversation_id,
    )

    report = RunReport(
        scenario_name=scenario.name,
        scenario_slug=scenario.slug,
        run_index=run_index,
        timestamp=timestamp,
        conversation_id=conversation_id,
        passed=passed,
        turns=turns,
        assertion_results=assertion_results,
        criteria_results=criteria_results,
        inspector_url=inspector_url,
        error=error,
        error_is_harness=error_is_harness,
        judge_results=judge_results,
        engine_tokens=engine_tokens,
        duration_s=duration_s,
        tool_scoring=tool_scoring_result,
        observed_tools=observed_tools,
        expected_tools=scenario.goals.expected_tools,
        tracker_events=tracker_events,
        evaluate_tool_calls=evaluate_tool_calls,
        repair_occurrences=_repair_occurrences_for_events(events),
    )
    _persist_run_report(report, project_path, experiment_timestamp)
    return report


_UNKNOWN_CONVERSATION_ID = "(run did not complete)"


def _write_incomplete_run_report(
    project_path: Path,
    experiment_timestamp: str,
    scenario: Scenario,
    run_index: int,
    error: BaseException,
) -> None:
    """Write a placeholder report for a run that produced none.

    A run cancelled by either timeout never reaches ``_run_once``'s own write,
    so without this the only trace is a log line on the server -- the caller is
    told the run failed and finds nothing on disk to explain why.

    Skips a run that already has a report. Today that cannot happen: nothing
    awaits between ``_run_once``'s try block and its write, so a run is either
    cancelled before that write or completes it and returns a result, and the
    harvest runs only once every task has been drained. That is a subtle
    invariant to rest on, though -- a single ``await`` added between the try
    and the write would let a cancelled run persist a real verdict that this
    then overwrote with a placeholder, losing it silently.

    Args:
        project_path: Root directory of the Rasa project.
        experiment_timestamp: Experiment folder name shared by every run.
        scenario: The scenario the run belonged to.
        run_index: 1-based index of the run within that scenario.
        error: What ended the run.
    """
    if run_report_path(
        project_path, experiment_timestamp, scenario.slug, run_index
    ).exists():
        structlogger.debug(
            "evaluate_agent.run_scenarios.placeholder_skipped",
            scenario=scenario.name,
            run_index=run_index,
        )
        return

    report = RunReport(
        scenario_name=scenario.name,
        scenario_slug=scenario.slug,
        run_index=run_index,
        timestamp=datetime.now(tz=timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
        conversation_id=_UNKNOWN_CONVERSATION_ID,
        passed=False,
        turns=[],
        assertion_results=[],
        criteria_results=[],
        inspector_url="",
        error=f"{type(error).__name__}: {error}",
    )
    # Same persistence path as a completed run, so the placeholder lands
    # beside its siblings and reaches W&B when that is enabled.
    _persist_run_report(report, project_path, experiment_timestamp)


def _is_harness_failure(report: RunReport) -> bool:
    """Whether a completed run failed the harness rather than the agent.

    Three ways a run can fail without the agent being at fault, and only the
    first reaches ``report.error``:

    * an exception during simulation or judging, unless ``_run_once`` marked it
      as an agent outcome -- a silent agent raises, but that is a verdict;
    * a criteria-judge outage, which ``run_llm_as_a_judge`` gathers with
      ``return_exceptions=True`` and parks on the results rather than raising;
    * a metrics-judge outage, the only signal for a scenario without criteria,
      since that skips the criteria judge entirely.

    Args:
        report: A run that produced a report, i.e. one that was not cancelled.

    Returns:
        True when the failure points at evaluation capacity, not the agent.
    """
    if report.error is not None:
        return report.error_is_harness
    judge = report.judge_results
    if judge is None:
        return False
    return judge.criteria.error is not None or judge.metrics.error is not None


async def run_scenarios(
    scenarios: List[Scenario],
    project_path: Path,
    experiment_timestamp: str,
    run_count: int,
    parallelism: int,
    rasa_server_url: str,
    simulation_llm_client: LLMClient,
    eval_llm_client: LLMClient,
    eval_llm_config: LLMConfig,
    simulated_user_prompt: Optional[str] = None,
    criteria_judge_prompt: Optional[str] = None,
    metrics_judge_prompt: Optional[str] = None,
    show_tracker_events: bool = False,
    evaluate_tool_calls: bool = False,
    simulation_max_concurrent_llm_calls: int = DEFAULT_MAX_CONCURRENT_LLM_CALLS,
    eval_max_concurrent_llm_calls: int = DEFAULT_MAX_CONCURRENT_LLM_CALLS,
    per_run_timeout_s: float = EVALUATE_AGENT_PER_RUN_TIMEOUT_S,
    batch_timeout_s: Optional[float] = None,
) -> Tuple[List[ScenarioSummaryEntry], float]:
    """Run every scenario ``run_count`` times concurrently and summarise each.

    Every ``(scenario, run)`` pair across ``scenarios`` and ``run_count`` is
    flattened into a single task grid executed under one semaphore sized by
    ``parallelism`` -- the scenario axis and the run axis are not treated
    separately. Each task carries its own timeout so one hung run cannot sink
    the rest of the batch.

    Args:
        scenarios: Scenarios to evaluate; each is run ``run_count`` times.
        project_path: Root directory of the Rasa project.
        experiment_timestamp: Experiment folder name shared by every run.
        run_count: Number of runs per scenario.
        parallelism: Maximum number of runs executing concurrently.
        rasa_server_url: Base URL of the running Rasa server.
        simulation_llm_client: LLM client driving the simulated user.
        eval_llm_client: LLM client used by the judge.
        eval_llm_config: Config describing ``eval_llm_client``'s model.
        simulated_user_prompt: Optional user-simulator prompt override.
        criteria_judge_prompt: Optional criteria-judge prompt override.
        metrics_judge_prompt: Optional metrics-judge prompt override.
        show_tracker_events: Include the tracker event debug dump in reports.
        evaluate_tool_calls: Score expected tool calls for each run.
        simulation_max_concurrent_llm_calls: Ceiling on simulation-role
            provider calls in flight across the whole batch.
        eval_max_concurrent_llm_calls: Ceiling on evaluation-role provider
            calls in flight across the whole batch. A run spends two of these
            while judging when the scenario defines criteria, one when it does
            not.
        per_run_timeout_s: Wall-clock budget for a single run.
        batch_timeout_s: Wall-clock budget for the whole grid. Runs still in
            flight when it expires are cancelled, and the scenarios that did
            finish are still summarised -- the budget is owned here rather
            than by a caller-side ``wait_for`` so that exhausting it degrades
            to partial results instead of discarding the entire batch.
            Defaults to the grid's own worst case (one ``per_run_timeout_s``
            per wave of ``parallelism`` runs) plus one wave of slack, capped
            at ``MAX_EVAL_BATCH_TIMEOUT_S``. A flat constant would cancel
            perfectly healthy runs as soon as a batch outgrew it, so the
            per-run timeout is the real guard and this is only a backstop
            against a batch running unbounded.

    Returns:
        One ``ScenarioSummaryEntry`` per scenario in input order, plus the
        elapsed seconds the grid took. A run that timed out, was cancelled,
        or raised counts as a failed run: ``runs_total`` always reflects the
        runs that were *requested*, and ``runs_errored`` reports how many of
        those failed for harness reasons rather than on their merits -- a
        timeout or cancellation (which gets a placeholder report), or any
        exception ``_run_once`` captured onto the report it returned, from
        either simulation or judging.

        Elapsed time is measured here rather than by the caller because each
        entry's ``duration_s`` sums that scenario's runs, which under
        concurrency measures compute rather than wall clock. The two diverge
        by roughly ``parallelism``, and only this function knows when the
        grid actually started and finished.

    Raises:
        ValueError: If ``parallelism`` is less than 1.

        Cancelling the caller cancels the whole grid: ``asyncio.wait`` does
        not cancel what it waits on, so the runs are cancelled and drained
        explicitly before ``asyncio.CancelledError`` propagates.
    """
    if parallelism < 1:
        # Semaphore(0) would deadlock until the batch timeout and a negative
        # value breaks the wave arithmetic below; neither is recoverable, so
        # fail loudly rather than hang.
        raise ValueError(f"parallelism must be >= 1, got {parallelism}")

    if not scenarios or run_count <= 0:
        # asyncio.wait rejects an empty set, and an empty grid has nothing to
        # summarise anyway. run_count is guarded here as well as at the tool
        # boundary so a direct caller gets [] rather than a ValueError from
        # deep inside asyncio.
        return [], 0.0

    async with aiohttp.ClientSession() as session:
        engine_version = await _fetch_engine_version(session, rasa_server_url)
    for scenario in scenarios:
        rejected_keys = assertion_keys_rejected_by_engine(
            engine_version, scenario.goals.assertions
        )
        if rejected_keys:
            raise EvalScenarioError(
                f"Scenario '{scenario.name}' assertions incompatible with "
                f"engine {engine_version}: {rejected_keys}"
            )

    project_memory = load_project_memory_schema(project_path)
    started_at = time.perf_counter()
    semaphore = asyncio.Semaphore(parallelism)
    # One semaphore per role for the whole batch, not per run: a per-run
    # semaphore would bound nothing, since each run holds its own. These are
    # deliberately independent of `parallelism` and of each other -- the two
    # roles can be different providers with different rate limits.
    simulation_llm_semaphore = asyncio.Semaphore(simulation_max_concurrent_llm_calls)
    eval_llm_semaphore = asyncio.Semaphore(eval_max_concurrent_llm_calls)
    grid = [
        (scenario_index, run_index)
        for scenario_index in range(len(scenarios))
        for run_index in range(1, run_count + 1)
    ]

    async def _bounded_run(scenario_index: int, run_index: int) -> RunReport:
        async with semaphore:
            # The timeout starts only after a slot is acquired, so a run
            # queued behind the semaphore is not charged for its wait.
            return await asyncio.wait_for(
                _run_once(
                    scenario=scenarios[scenario_index],
                    run_index=run_index,
                    project_path=project_path,
                    experiment_timestamp=experiment_timestamp,
                    rasa_server_url=rasa_server_url,
                    simulation_llm_client=simulation_llm_client,
                    eval_llm_client=eval_llm_client,
                    eval_llm_config=eval_llm_config,
                    simulated_user_prompt=simulated_user_prompt,
                    criteria_judge_prompt=criteria_judge_prompt,
                    metrics_judge_prompt=metrics_judge_prompt,
                    show_tracker_events=show_tracker_events,
                    evaluate_tool_calls=evaluate_tool_calls,
                    project_memory=project_memory,
                    simulation_llm_semaphore=simulation_llm_semaphore,
                    eval_llm_semaphore=eval_llm_semaphore,
                    engine_version=engine_version,
                ),
                timeout=per_run_timeout_s,
            )

    tasks = {
        asyncio.create_task(_bounded_run(scenario_index, run_index)): (
            scenario_index,
            run_index,
        )
        for scenario_index, run_index in grid
    }
    if batch_timeout_s is None:
        # ceil(cells / parallelism) * per_run is the exact worst-case makespan,
        # not a bound above it: the last run starts by wave boundary
        # floor((n-1)/p) and ends one per_run_timeout_s later. Budgeting that
        # precisely makes the deadline tie with the final completion, so a
        # healthy last wave races the cancel. One extra wave of slack absorbs
        # that plus scheduling overhead.
        waves = math.ceil(len(grid) / parallelism)
        batch_timeout_s = min((waves + 1) * per_run_timeout_s, MAX_EVAL_BATCH_TIMEOUT_S)

    pending: set = set()
    try:
        _, pending = await asyncio.wait(tasks.keys(), timeout=batch_timeout_s)
    except asyncio.CancelledError:
        # asyncio.wait does not cancel what it is waiting on when it is itself
        # cancelled, so without this the whole grid would keep running -- and
        # keep spending LLM calls against a caller that has already gone away.
        pending = {task for task in tasks if not task.done()}
        raise
    finally:
        for task in pending:
            task.cancel()
        if pending:
            # Let the cancellations settle so each run's aiohttp session
            # unwinds before this returns. A second cancellation arriving
            # mid-drain must not mask the one already propagating.
            with suppress(asyncio.CancelledError):
                await asyncio.gather(*pending, return_exceptions=True)

    reports: Dict[int, List[RunReport]] = {index: [] for index in range(len(scenarios))}
    errored: Dict[int, int] = {index: 0 for index in range(len(scenarios))}
    for task, (scenario_index, run_index) in tasks.items():
        error: Optional[BaseException] = None
        if task.cancelled():
            error = asyncio.CancelledError("batch timeout expired")
        else:
            error = task.exception()
            if error is None:
                report = task.result()
                reports[scenario_index].append(report)
                # A completed report can still be a harness failure -- see
                # _is_harness_failure for the three ways that happens.
                if _is_harness_failure(report):
                    errored[scenario_index] += 1
                continue
        # A run that timed out, was cancelled, or raised never reached
        # _run_once's own write, but it was still a requested run. It is
        # counted as a failure below rather than dropped -- deriving
        # runs_total from the surviving results would report a batch with one
        # timed-out run as 2/2 passed. It is also counted separately, and given
        # a placeholder report, so the caller can tell "the agent failed" from
        # "the run never produced a verdict" and has something on disk either
        # way.
        errored[scenario_index] += 1
        _write_incomplete_run_report(
            project_path=project_path,
            experiment_timestamp=experiment_timestamp,
            scenario=scenarios[scenario_index],
            run_index=run_index,
            error=error,
        )
        structlogger.warning(
            "evaluate_agent.run_scenarios.run_failed",
            scenario=scenarios[scenario_index].name,
            run_index=run_index,
            error_type=type(error).__name__,
            error=str(error),
        )

    entries = [
        ScenarioSummaryEntry(
            scenario_name=scenario.name,
            scenario_slug=scenario.slug,
            runs_passed=sum(report.passed for report in reports[index]),
            runs_total=run_count,
            runs_errored=errored[index],
            duration_s=sum(report.duration_s for report in reports[index]),
        )
        for index, scenario in enumerate(scenarios)
    ]
    return entries, time.perf_counter() - started_at
